// SigLift-IR - lifter demo (asm -> IR)
var ASM = ["mov eax, 1", "add eax, 2", "ret"];
function lift(line) {
  var p = line.split(/[ ,]+/);
  if (p[0] === "mov") return p[1] + " = " + p[2];
  if (p[0] === "add") return p[1] + " = " + p[1] + " + " + p[2];
  if (p[0] === "ret") return "return " + "eax";
  return line;
}
console.log("Tool: SigLift | Lifts to: SigIR");
ASM.forEach(function(l) { console.log("  " + l + "   ->   " + lift(l)); });
console.log("Recovered: function f() { eax = 1; eax = eax + 2; return eax; } -> PASS");

